function rangoFaltante(ids, lo, hi) {
  const presentes = ids
    .filter(id => id >= lo && id <= hi)
    .sort((a, b) => a - b);

  const faltantes = [];
  let inicio = lo;

  for (const id of presentes) {
    if (id < inicio) continue;

    if (id > inicio) {
      faltantes.push([inicio, id - 1]);
    }
    inicio = id + 1;
  }

  if (inicio <= hi) {
    faltantes.push([inicio, hi]);
  }

  return faltantes;
}
```

