function leerRegistro(s) {
  const campos = [];
  let i = 0;

  while (true) {
    let campo = "";

    if (s[i] === '"') {
      i++;

      while (true) {
        if (i === s.length) return null;

        if (s[i] !== '"') {
          campo += s[i++];
        } else if (s[i + 1] === '"') {
          campo += '"';
          i += 2;
        } else {
          i++;
          break;
        }
      }
    } else {
      const inicio = i;

      while (i < s.length && s[i] !== ",") {
        if (s[i] === '"') return null;
        i++;
      }

      campo = s.slice(inicio, i);
    }

    campos.push(campo);
    if (i === s.length) return campos;
    if (s[i] !== ",") return null;
    i++;
  }
}
