function beneficioMaximo(trabajos) {
  const ordenados = trabajos.slice().sort((a, b) => a[1] - b[1]);
  const dp = new Array(ordenados.length + 1).fill(0);

  for (let i = 0; i < ordenados.length; i++) {
    const [inicio, , puntos] = ordenados[i];
    let izquierda = 0;
    let derecha = i;

    // Busca cuántos trabajos anteriores terminan a tiempo.
    while (izquierda < derecha) {
      const medio = Math.floor((izquierda + derecha) / 2);
      if (ordenados[medio][1] <= inicio) {
        izquierda = medio + 1;
      } else {
        derecha = medio;
      }
    }

    dp[i + 1] = Math.max(dp[i], puntos + dp[izquierda]);
  }

  return dp[ordenados.length];
}
